import React, { useEffect, useState } from "react";
import { Truck, HardHat } from "lucide-react";
import SignIn from "./SignIn";

const WorkerSplash = () => {

  const [showLogin, setShowLogin] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => {
      setShowLogin(true);
    }, 9000);

    return () => clearTimeout(timer);
  }, []);

  return (
    <div className="h-screen w-screen bg-[#FDFAD8] flex items-center justify-center relative overflow-hidden">

      {/* Splash Content */}
      {!showLogin && (
        <div className="text-center">

          <div className="flex justify-center mb-10">
            <div className="w-28 h-28 bg-[#CAD23C] rounded-[30px] flex items-center justify-center text-[#47510B] shadow-xl">
              <Truck size={48}/>
            </div>
          </div>

          <h1 className="text-7xl font-black italic text-[#47510B] uppercase tracking-tighter">
            Worker<br/>Terminal
          </h1>

          <p className="mt-6 text-xs font-black uppercase tracking-[0.4em] text-[#47510B]/40">
            Trash2Track Operations
          </p>

        </div>
      )}

      {/* Login */}
      {showLogin && <SignIn/>}

    </div>
  );
};

export default WorkerSplash;
